import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../..");
const migrations = path.join(root, "drizzle", "migrations");
const out = path.join(root, "backend", "sql", "01_schema.sql");

const include = [
  "0000_migration.sql",
  "0001_migration.sql",
  "0002_expenses_module.sql",
  "0004_biory_master_data.sql",
  "0005_staff_requisitions.sql",
];

const header = `-- BIORY distribution schema for a standalone Postgres database.
-- Generated by backend/scripts/build_schema.py — regenerate instead of editing.
-- The API connects as biory_app. Tables are owned by the migration role, so
-- row level security applies to the API. SECURITY DEFINER functions keep the
-- ledger rules atomic and run as the owner.

create or replace function public.current_user_id() returns uuid
language sql stable
set search_path = public
as $$
  select nullif(current_setting('app.user_id', true), '')::uuid
$$;

`;

const users = `create table public.users (
  id uuid primary key default gen_random_uuid(),
  email text not null unique,
  password_hash text not null,
  full_name text not null default '',
  email_confirmed_at timestamptz,
  created_at timestamptz not null default now()
);

`;

const footer = `
revoke execute on all functions in schema public from public;
grant usage on schema public to biory_app;
grant select, insert, update, delete on all tables in schema public to biory_app;
grant usage, select on all sequences in schema public to biory_app;
grant execute on all functions in schema public to biory_app;

-- Helpers that must only run inside other functions, not as API calls.
revoke execute on function public.next_doc_no(text) from biory_app;
revoke execute on function public._allocate_fefo(uuid, uuid, int) from biory_app;
revoke execute on function public._notify_user(uuid, text, text, text) from biory_app;
revoke execute on function public._notify_roles(public.app_role[], text, text, text) from biory_app;
revoke execute on function public._audit(text, text, text, jsonb, text) from biory_app;
revoke execute on function public._refresh_order_status(uuid) from biory_app;
revoke execute on function public._so_reserved(uuid, uuid) from biory_app;
revoke execute on function public._usable_qty(uuid, uuid) from biory_app;
`;

function stripPrivileges(sql) {
  return sql
    .split(/\r?\n/)
    .filter((line) => !/^\s*(grant|revoke)\b/i.test(line))
    .join("\n");
}

let sql = include.map((name) => fs.readFileSync(path.join(migrations, name), "utf8")).join("\n\n");
sql = sql.replace(/create policy\s+"[^"]*"\s+on storage\.[\s\S]*?;\s*/gi, "");
sql = stripPrivileges(sql);
sql = sql.replaceAll("auth.uid()", "public.current_user_id()");
sql = sql.replaceAll("auth.users", "public.users");
sql = sql.replaceAll(" to authenticated", "");
sql = sql.replaceAll(" to anon", "");
sql = sql.replaceAll(
  "coalesce(new.raw_user_meta_data->>'full_name', new.raw_user_meta_data->>'name', split_part(new.email, '@', 1))",
  "coalesce(nullif(trim(new.full_name), ''), split_part(new.email, '@', 1))",
);
const marker = "create table public.profiles (";
if (!sql.includes(marker)) throw new Error("profiles table not found");
sql = sql.replace(marker, users + marker);
sql = header + sql.trim() + "\n" + footer;
if (sql.includes("auth.users") || sql.includes("auth.uid()") || sql.includes("storage.")) {
  throw new Error("schema still references Supabase auth or storage");
}
fs.mkdirSync(path.dirname(out), { recursive: true });
fs.writeFileSync(out, sql.replaceAll("\r\n", "\n"), "utf8");
console.log(`wrote ${out} (${sql.split("\n").length} lines)`);
